/**
 * The workspace read-only rule: which subscription states refuse writes, and
 * the error every locked write throws.
 */
import type { OrgId } from "@/types/common";
import type { Subscription, WorkspaceLockReason } from "@/types/billing";

/** Thrown by `assertWorkspaceWritable()`; mapped to `plan_limit_exceeded`. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace ${orgId} is read-only: ${reason}`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * Pure rule deciding whether a subscription leaves its workspace writable.
 *
 * No subscription row, or an `active` one, is writable. `past_due` always
 * locks. `trialing` locks once the trial's period end is reached. `canceled`
 * locks from its cancellation date — a cancellation scheduled for later
 * keeps the workspace writable until then, and a missing cancellation date
 * counts as canceled now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;

    case "past_due":
      return "past_due";

    case "trialing":
      return now.getTime() >= new Date(subscription.currentPeriodEnd).getTime()
        ? "trial_ended"
        : null;

    case "canceled": {
      if (subscription.cancelAt === null) return "canceled";
      return now.getTime() >= new Date(subscription.cancelAt).getTime()
        ? "canceled"
        : null;
    }
  }
}

