/**
 * `lockReasonFor` — the pure rule deciding whether a subscription leaves its
 * workspace writable — and the `WorkspaceLockedError` shape it backs.
 */
import { describe, expect, it } from "vitest";
import { WorkspaceLockedError, lockReasonFor } from "@/lib/billing-lock";
import { toIsoTimestamp } from "@/types/common";
import { ORG_A } from "../helpers/factories";
import type { Subscription } from "@/types/billing";

const NOW = new Date("2026-06-15T00:00:00.000Z");

function makeSubscription(overrides: Partial<Subscription> = {}): Subscription {
  return {
    id: "01HZZZSUBSUBSUBSUBSUBSUB1" as Subscription["id"],
    orgId: ORG_A,
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 5,
    currentPeriodStart: toIsoTimestamp(new Date("2026-06-01T00:00:00.000Z")),
    currentPeriodEnd: toIsoTimestamp(new Date("2026-07-01T00:00:00.000Z")),
    cancelAt: null,
    createdAt: toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
    updatedAt: toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
    ...overrides,
  };
}

describe("lib/billing-lock", () => {
  it("leaves a workspace with no subscription row writable", () => {
    expect(lockReasonFor(null, NOW)).toBeNull();
  });

  it("leaves an active subscription writable", () => {
    expect(lockReasonFor(makeSubscription({ status: "active" }), NOW)).toBeNull();
  });

  it("always locks a past_due subscription", () => {
    expect(lockReasonFor(makeSubscription({ status: "past_due" }), NOW)).toBe(
      "past_due",
    );
  });

  it("keeps a trialing subscription writable before its period end", () => {
    const subscription = makeSubscription({
      status: "trialing",
      currentPeriodEnd: toIsoTimestamp(new Date("2026-06-20T00:00:00.000Z")),
    });
    expect(lockReasonFor(subscription, NOW)).toBeNull();
  });

  it("locks a trialing subscription once its period end is reached", () => {
    const atPeriodEnd = makeSubscription({
      status: "trialing",
      currentPeriodEnd: toIsoTimestamp(NOW),
    });
    expect(lockReasonFor(atPeriodEnd, NOW)).toBe("trial_ended");

    const pastPeriodEnd = makeSubscription({
      status: "trialing",
      currentPeriodEnd: toIsoTimestamp(new Date("2026-06-01T00:00:00.000Z")),
    });
    expect(lockReasonFor(pastPeriodEnd, NOW)).toBe("trial_ended");
  });

  it("keeps a canceled subscription writable until its scheduled cancellation date", () => {
    const scheduledLater = makeSubscription({
      status: "canceled",
      cancelAt: toIsoTimestamp(new Date("2026-06-20T00:00:00.000Z")),
    });
    expect(lockReasonFor(scheduledLater, NOW)).toBeNull();
  });

  it("locks a canceled subscription once its cancellation date is reached", () => {
    const atCancelAt = makeSubscription({
      status: "canceled",
      cancelAt: toIsoTimestamp(NOW),
    });
    expect(lockReasonFor(atCancelAt, NOW)).toBe("canceled");

    const pastCancelAt = makeSubscription({
      status: "canceled",
      cancelAt: toIsoTimestamp(new Date("2026-06-01T00:00:00.000Z")),
    });
    expect(lockReasonFor(pastCancelAt, NOW)).toBe("canceled");
  });

  it("treats a canceled subscription with no cancellation date as canceled now", () => {
    const noCancelAt = makeSubscription({ status: "canceled", cancelAt: null });
    expect(lockReasonFor(noCancelAt, NOW)).toBe("canceled");
  });

  it("defaults `now` to the current time", () => {
    const pastDue = makeSubscription({ status: "past_due" });
    expect(lockReasonFor(pastDue)).toBe("past_due");
  });

  it("carries the org id and reason on WorkspaceLockedError", () => {
    const error = new WorkspaceLockedError(ORG_A, "past_due");
    expect(error.code).toBe("plan_limit_exceeded");
    expect(error.orgId).toBe(ORG_A);
    expect(error.reason).toBe("past_due");
  });
});

