// Accepting into a locked workspace is refused and creates no membership;
// the invitation itself stays pending, not accepted.
it("refuses to accept an invitation into a locked workspace", async () => {
  const tenant = await createTenant("invite-locked", "growth");
  await subscriptionRepo.cancelSubscription(
    tenant.org.id,
    toIsoTimestamp(new Date()),
  );

  const rawToken = "d".repeat(32);
  const invitation = await invitationRepo.insertInvitation(
    tenant.org.id,
    {
      orgId: tenant.org.id,
      email: "locked-out@invite-locked.test",
      role: "member",
      expiresInDays: 14,
    },
    tenant.userIds.admin,
    hashToken(rawToken),
  );

  const newUser = await userRepo.insertUser({
    email: "locked-out@invite-locked.test",
    name: "Locked Out",
    passwordHash: "seed",
  });

  await expect(
    invitationService.acceptInvitation(newUser.id, { token: rawToken }),
  ).rejects.toBeInstanceOf(WorkspaceLockedError);

  await expect(
    memberRepo.findMember(tenant.org.id, newUser.id),
  ).resolves.toBeNull();

  const stillPending = await invitationRepo.findInvitationByTokenHash(
    hashToken(rawToken),
  );
  expect(stillPending?.id).toBe(invitation.id);
  expect(stillPending?.acceptedAt).toBeNull();
});

// Sending, revoking and re-sending an invite are all refused once locked.
it("refuses to send, revoke or resend an invitation in a locked workspace", async () => {
  const tenant = await createTenant("invite-locked-writes", "growth");

  const invitation = await invitationService.inviteMember(tenant.actors.admin, {
    orgId: tenant.org.id,
    email: "before-lock@invite-locked-writes.test",
    role: "member",
  });

  await subscriptionRepo.cancelSubscription(
    tenant.org.id,
    toIsoTimestamp(new Date()),
  );

  await expect(
    invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "after-lock@invite-locked-writes.test",
      role: "member",
    }),
  ).rejects.toBeInstanceOf(WorkspaceLockedError);

  await expect(
    invitationService.revokeInvitation(tenant.actors.admin, invitation.id),
  ).rejects.toBeInstanceOf(WorkspaceLockedError);

  await expect(
    invitationService.resendInvitation(tenant.actors.admin, invitation.id),
  ).rejects.toBeInstanceOf(WorkspaceLockedError);
});

// An expired or revoked token is refused rather than silently accepted.

